const { readFileSync, existsSync } = await import('node:fs');
if (!input.pdf_path || !existsSync(input.pdf_path)) {
  throw new Error('PDF file not found at provided path');
}
globalThis.pdfBytes = readFileSync(input.pdf_path);

const mod = await import('pdf-lib');
const PDFDocument = mod.PDFDocument || mod.default?.PDFDocument || mod.default;
const pdfDoc = await PDFDocument.load(globalThis.pdfBytes);
let title = '';
if (typeof pdfDoc.getTitle === 'function') {
  title = pdfDoc.getTitle() || '';
}
globalThis.heading = title;

if (globalThis.heading === undefined) {
  throw new Error('Heading extraction resulted in undefined');
}
console.log(JSON.stringify({ heading: globalThis.heading }));
